-- ============================================================
--  Experiencias de clase: Curso de Asuntos Regulatorios Farmacéuticos en Colombia
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  33 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Asuntos Regulatorios Farmacéuticos en Colombia$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Asuntos Regulatorios Farmacéuticos en Colombia$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: el mapa de los asuntos regulatorios en Colombia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: el mapa de los asuntos regulatorios en Colombia$t$
     AND m.title = $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: el mapa de los asuntos regulatorios en Colombia$t$, $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: el mapa de los asuntos regulatorios en Colombia","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de introducción al curso: el mapa de los asuntos regulatorios en Colombia. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: el mapa de los asuntos regulatorios en Colombia con tus propias palabras y reconocer por qué importa en curso de Asuntos Regulatorios Farmacéuticos en Colombia.","Relacionar introducción al curso: el mapa de los asuntos regulatorios en Colombia con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: el mapa de los asuntos regulatorios en Colombia y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El estudiante conoce la estructura del curso y una visión general de autoridades, normas, categorías de producto y ciclo de vida regulatorio."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción al curso: el mapa de los asuntos regulatorios en Colombia aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda la función regulatoria y el sistema sanitario colombiano, identifique el régimen aplicable a cada categoría de producto y su ciclo de vida, y formule estrategias e inteligencia regulatoria alineadas con la normativa vigente y la armonización internacional. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El estudiante conoce la estructura del curso y una visión general de autoridades, normas, categorías de producto y ciclo de vida regulatorio.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa funcional del área de asuntos regulatorios.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: el mapa de los asuntos regulatorios en Colombia, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las categorías de producto y sus normas. Evidencia que debe quedar: Registro del paso.","Diseña el inventario regulatorio (qué datos de cada registro se controlan). Evidencia que debe quedar: Registro del paso.","Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos. Evidencia que debe quedar: Registro del paso.","Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste. Evidencia que debe quedar: Registro del paso.","Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables. Evidencia que debe quedar: Registro del paso.","Propón cuatro indicadores del área con fórmula y meta. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un laboratorio ficticio, mercadeo quiere lanzar en un mes una nueva presentación de un analgésico con la frase «alivio en 10 minutos» en el empaque, sin estudios que la respalden y con un arte distinto del aprobado. La analista de asuntos regulatorios dice que no es posible; el gerente comercial la acusa de «frenar el negocio» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: el mapa de los asuntos regulatorios en Colombia en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: el mapa de los asuntos regulatorios en Colombia»?","respuesta":"El estudiante conoce la estructura del curso y una visión general de autoridades, normas, categorías de producto y ciclo de vida regulatorio."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa funcional del área de asuntos regulatorios.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción al curso: el mapa de los asuntos regulatorios en Colombia se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Diplomado en Asuntos regulatorios sobre medicamentos biológicos y de síntesis química (contenidos y módulos). Universidad El Bosque (ES)","url":"https://www.unbosque.edu.co/sites/default/files/2025-07/Diplomado%20en%20Asuntos%20regulatorios%20sobre%20medicamentos%20biologicos%20y%20de%20sintesis%20quimica.pdf"},{"cita":"[Página web] El Invima lidera la transformación regulatoria en el XIII Congreso Nacional de Ciencias Farmacéuticas. INVIMA (ES)","url":"https://www.invima.gov.co/blog/sala-de-prensa-13/el-invima-lidera-la-transformacion-regulatoria-en-el-xiii-congreso-nacional-de-ciencias-farmaceutica-157"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: el mapa de los asuntos regulatorios en Colombia en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción al curso: el mapa de los asuntos regulatorios en Colombia"}],"keywords":["curso","asuntos","regulatorios","farmacéuticos","colombia","introducción","unidad","fundamentos","químico","farmacéutico"],"mapa":{"centro":"Introducción al curso: el mapa de los asuntos regulatorios en Colombia","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa funcional de un departamento de asuntos regulatorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las categorías de producto y sus normas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Diseña el inventario regulatorio (qué datos de cada registro se controlan).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón cuatro indicadores del área con fórmula y meta.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Mapa funcional de un departamento de asuntos regulatorios","contexto":"Laboratorios Cóndor (ficticio) es titular de 40 registros de medicamentos (8 biológicos registrados hace años bajo el Decreto 677), 12 suplementos dietarios y 5 dispositivos médicos. Hoy no tiene un área de asuntos regulatorios: cada gerente de producto «lleva sus registros» en hojas de cálculo distintas, hubo un requerimiento vencido el año pasado y nadie sabe qué productos llevan más de 30 días sin comercializarse (datos simulados). La dirección quiere crear el área.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: el mapa de los asuntos regulatorios en Colombia?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. ¿Qué son los asuntos regulatorios y por qué existen?
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$¿Qué son los asuntos regulatorios y por qué existen?$t$
     AND m.title = $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$¿Qué son los asuntos regulatorios y por qué existen?$t$, $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"¿Qué son los asuntos regulatorios y por qué existen?","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de ¿Qué son los asuntos regulatorios y por qué existen?. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar ¿Qué son los asuntos regulatorios y por qué existen? con tus propias palabras y reconocer por qué importa en curso de Asuntos Regulatorios Farmacéuticos en Colombia.","Relacionar ¿Qué son los asuntos regulatorios y por qué existen? con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar ¿Qué son los asuntos regulatorios y por qué existen? y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Comprende la razón de ser de la función regulatoria, sus objetivos y su relación con calidad, mercadeo y negocio. comprender qué es la función de asuntos regulatorios (AR) en la industria farmacéutica colombiana y por qué existe. Los asuntos regulatorios son la disciplina que conecta a la empresa con la autoridad sanitaria. Su razón de ser es que ningún medicamento, biológico, fitoterapéutico, dispositivo médico o cosmético puede fabricarse,…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, ¿Qué son los asuntos regulatorios y por qué existen? aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda la función regulatoria y el sistema sanitario colombiano, identifique el régimen aplicable a cada categoría de producto y su ciclo de vida, y formule estrategias e inteligencia regulatoria alineadas con la normativa vigente y la armonización internacional. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Comprende la razón de ser de la función regulatoria, sus objetivos y su relación con calidad, mercadeo y negocio. comprender qué es la función de asuntos regulatorios (AR) en la industria farmacéutica colombiana y por qué existe. Los asuntos regulatorios son la disciplina que conecta a la empresa con la autoridad sanitaria. Su razón de ser es que ningún medicamento, biológico, fitoterapéutico, dispositivo médico o cosmético puede fabricarse,…","Una pregunta que se usa para comprobar esta clase es: «¿Cuál es la razón de ser de la función de asuntos regulatorios en una empresa farmacéutica?» La respuesta correcta se apoya en lo siguiente: Asuntos regulatorios asegura que los productos obtengan y mantengan su autorización de comercialización, cumpliendo las normas sanitarias, y articula la evidencia técnica con las decisiones de negocio. La fuente citada es: Decreto 677 de 1995; Decreto 334 de 2022.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa funcional del área de asuntos regulatorios.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar ¿Qué son los asuntos regulatorios y por qué existen?, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las categorías de producto y sus normas. Evidencia que debe quedar: Registro del paso.","Diseña el inventario regulatorio (qué datos de cada registro se controlan). Evidencia que debe quedar: Registro del paso.","Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos. Evidencia que debe quedar: Registro del paso.","Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste. Evidencia que debe quedar: Registro del paso.","Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables. Evidencia que debe quedar: Registro del paso.","Propón cuatro indicadores del área con fórmula y meta. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un laboratorio ficticio, mercadeo quiere lanzar en un mes una nueva presentación de un analgésico con la frase «alivio en 10 minutos» en el empaque, sin estudios que la respalden y con un arte distinto del aprobado. La analista de asuntos regulatorios dice que no es posible; el gerente comercial la acusa de «frenar el negocio» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar ¿Qué son los asuntos regulatorios y por qué existen? en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «¿Qué son los asuntos regulatorios y por qué existen?»?","respuesta":"Comprende la razón de ser de la función regulatoria, sus objetivos y su relación con calidad, mercadeo y negocio. comprender qué es la función de asuntos regulatorios (AR) en la industria farmacéutica colombiana y por qué existe. Los asuntos regulatorios son la disciplina que conecta a la empresa con la autoridad sanitaria. Su razón de ser es que ningún medicamento, biológico, fitoterapéutico, dispositivo médico o cosmético puede fabricarse,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa funcional del área de asuntos regulatorios.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["¿Qué son los asuntos regulatorios y por qué existen? se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente ¿Qué son los asuntos regulatorios y por qué existen? en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de ¿Qué son los asuntos regulatorios y por qué existen?"}],"keywords":["curso","asuntos","regulatorios","farmacéuticos","colombia","existen","unidad","fundamentos","químico","farmacéutico"],"mapa":{"centro":"¿Qué son los asuntos regulatorios y por qué existen?","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa funcional de un departamento de asuntos regulatorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las categorías de producto y sus normas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Diseña el inventario regulatorio (qué datos de cada registro se controlan).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón cuatro indicadores del área con fórmula y meta.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"¿Qué son los asuntos regulatorios y por qué existen?","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico: Laboratorios Cóndor (ficticio) es titular de 40 registros de medicamentos (8 biológicos registrados hace años bajo el Decreto 677), 12 suplementos dietarios y 5 dispositivos médicos. Hoy no tiene un área de asuntos regulatorios: cada gerente de producto «lleva sus registros» en hojas de cálculo distintas, hubo un requerimiento vencido el año pasado y nadie sabe qué productos llevan más de 30 días sin comercializarse (datos simulados). La dirección quiere crear el área. La pregunta que decide esta clase es: ¿Cuál es la razón de ser de la función de asuntos regulatorios en una empresa farmacéutica?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Negociar con el Invima excepciones a los requisitos para acelerar los lanzamientos de la empresa.","correcta":false,"retro":"La función no busca excepciones, sino cumplir y demostrar el cumplimiento."},{"texto":"Diseñar las campañas de mercadeo de los productos nuevos para todos los canales digitales.","correcta":false,"retro":"El mercadeo es otra función; asuntos regulatorios vigila que la información cumpla."},{"texto":"Reemplazar al área de calidad en la liberación de los lotes cuando hay mucha carga de trabajo.","correcta":false,"retro":"La liberación es de calidad, no de asuntos regulatorios."},{"texto":"Lograr y mantener la autorización de los productos cumpliendo las normas que protegen al paciente.","correcta":true,"retro":"Correcto. Conecta la ciencia, la norma y el negocio."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Rol, competencias y responsabilidades del QF en asuntos regulatorios
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Rol, competencias y responsabilidades del QF en asuntos regulatorios$t$
     AND m.title = $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Rol, competencias y responsabilidades del QF en asuntos regulatorios$t$, $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Rol, competencias y responsabilidades del QF en asuntos regulatorios","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de rol, competencias y responsabilidades del QF en asuntos regulatorios. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar rol, competencias y responsabilidades del QF en asuntos regulatorios con tus propias palabras y reconocer por qué importa en curso de Asuntos Regulatorios Farmacéuticos en Colombia.","Relacionar rol, competencias y responsabilidades del QF en asuntos regulatorios con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar rol, competencias y responsabilidades del QF en asuntos regulatorios y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Identifica perfiles de cargo (analista, coordinador, director técnico de AR), competencias técnicas y responsabilidades legales del QF frente a INVIMA."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, rol, competencias y responsabilidades del QF en asuntos regulatorios aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda la función regulatoria y el sistema sanitario colombiano, identifique el régimen aplicable a cada categoría de producto y su ciclo de vida, y formule estrategias e inteligencia regulatoria alineadas con la normativa vigente y la armonización internacional. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Identifica perfiles de cargo (analista, coordinador, director técnico de AR), competencias técnicas y responsabilidades legales del QF frente a INVIMA.","Una pregunta que se usa para comprobar esta clase es: «Un analista de asuntos regulatorios descubre que el arte de un empaque que se va a imprimir no coincide con el aprobado en el registro. ¿Qué le corresponde hacer?» La respuesta correcta se apoya en lo siguiente: La información del empaque y la etiqueta aprobada hace parte de las condiciones del registro; los cambios se tramitan según su clasificación (Decreto 334 de 2022) antes de implementarse. La fuente citada es: Decreto 334 de 2022, artículos 5 y 8.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa funcional del área de asuntos regulatorios.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar rol, competencias y responsabilidades del QF en asuntos regulatorios, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las categorías de producto y sus normas. Evidencia que debe quedar: Registro del paso.","Diseña el inventario regulatorio (qué datos de cada registro se controlan). Evidencia que debe quedar: Registro del paso.","Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos. Evidencia que debe quedar: Registro del paso.","Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste. Evidencia que debe quedar: Registro del paso.","Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables. Evidencia que debe quedar: Registro del paso.","Propón cuatro indicadores del área con fórmula y meta. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar rol, competencias y responsabilidades del QF en asuntos regulatorios en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Rol, competencias y responsabilidades del QF en asuntos regulatorios»?","respuesta":"Identifica perfiles de cargo (analista, coordinador, director técnico de AR), competencias técnicas y responsabilidades legales del QF frente a INVIMA."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa funcional del área de asuntos regulatorios.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Rol, competencias y responsabilidades del QF en asuntos regulatorios se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Diplomado en Asuntos regulatorios sobre medicamentos biológicos y de síntesis química (contenidos y módulos). Universidad El Bosque (ES)","url":"https://www.unbosque.edu.co/sites/default/files/2025-07/Diplomado%20en%20Asuntos%20regulatorios%20sobre%20medicamentos%20biologicos%20y%20de%20sintesis%20quimica.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente rol, competencias y responsabilidades del QF en asuntos regulatorios en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de rol, competencias y responsabilidades del QF en asuntos regulatorios"}],"keywords":["curso","asuntos","regulatorios","farmacéuticos","colombia","competencias","responsabilidades","unidad","fundamentos","químico","farmacéutico"],"mapa":{"centro":"Rol, competencias y responsabilidades del QF en asuntos regulatorios","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa funcional de un departamento de asuntos regulatorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las categorías de producto y sus normas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Diseña el inventario regulatorio (qué datos de cada registro se controlan).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón cuatro indicadores del área con fórmula y meta.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Rol, competencias y responsabilidades del QF en asuntos regulatorios","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico: Laboratorios Cóndor (ficticio) es titular de 40 registros de medicamentos (8 biológicos registrados hace años bajo el Decreto 677), 12 suplementos dietarios y 5 dispositivos médicos. Hoy no tiene un área de asuntos regulatorios: cada gerente de producto «lleva sus registros» en hojas de cálculo distintas, hubo un requerimiento vencido el año pasado y nadie sabe qué productos llevan más de 30 días sin comercializarse (datos simulados). La dirección quiere crear el área. La pregunta que decide esta clase es: Un analista de asuntos regulatorios descubre que el arte de un empaque que se va a imprimir no coincide con el aprobado en el registro. ¿Qué le corresponde hacer?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Autorizar la impresión, porque las diferencias de diseño gráfico no afectan las condiciones del registro.","correcta":false,"retro":"El arte aprobado es parte de las condiciones del registro."},{"texto":"Detener la impresión y gestionar la corrección o la modificación que corresponda antes de usarlo.","correcta":true,"retro":"Correcto. Ningún material se usa si no corresponde a lo aprobado."},{"texto":"Informar al área de mercadeo y dejar que decida si se imprime o no el nuevo material de empaque.","correcta":false,"retro":"La decisión sobre el cumplimiento regulatorio no se delega a mercadeo."},{"texto":"Imprimirlo y solicitar después al Invima que apruebe el nuevo arte por excepción.","correcta":false,"retro":"No existe una aprobación posterior por excepción para un material ya en uso."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 04. Ciencia regulatoria y tendencias de transformación del INVIMA
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Ciencia regulatoria y tendencias de transformación del INVIMA$t$
     AND m.title = $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Ciencia regulatoria y tendencias de transformación del INVIMA$t$, $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Ciencia regulatoria y tendencias de transformación del INVIMA","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de ciencia regulatoria y tendencias de transformación del INVIMA. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar ciencia regulatoria y tendencias de transformación del INVIMA con tus propias palabras y reconocer por qué importa en curso de Asuntos Regulatorios Farmacéuticos en Colombia.","Relacionar ciencia regulatoria y tendencias de transformación del INVIMA con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar ciencia regulatoria y tendencias de transformación del INVIMA y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta el concepto de ciencia regulatoria y las iniciativas recientes de INVIMA (gestión de represamiento, digitalización, enfoque de riesgo)."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, ciencia regulatoria y tendencias de transformación del INVIMA aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda la función regulatoria y el sistema sanitario colombiano, identifique el régimen aplicable a cada categoría de producto y su ciclo de vida, y formule estrategias e inteligencia regulatoria alineadas con la normativa vigente y la armonización internacional. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta el concepto de ciencia regulatoria y las iniciativas recientes de INVIMA (gestión de represamiento, digitalización, enfoque de riesgo).","Una pregunta que se usa para comprobar esta clase es: «Un gerente afirma que «la digitalización y el enfoque de riesgo del Invima significan que ya no hay que preparar bien los expedientes». ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: La digitalización y el enfoque de riesgo cambian cómo se tramita, no qué se demuestra. Incluso los trámites automáticos tienen control posterior: el Decreto 334 de 2022 permite suspender registros por inconsistencias detectadas en ese control. La fuente citada es: Decreto 334 de 2022, artículo 21.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa funcional del área de asuntos regulatorios.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar ciencia regulatoria y tendencias de transformación del INVIMA, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las categorías de producto y sus normas. Evidencia que debe quedar: Registro del paso.","Diseña el inventario regulatorio (qué datos de cada registro se controlan). Evidencia que debe quedar: Registro del paso.","Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos. Evidencia que debe quedar: Registro del paso.","Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste. Evidencia que debe quedar: Registro del paso.","Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables. Evidencia que debe quedar: Registro del paso.","Propón cuatro indicadores del área con fórmula y meta. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un laboratorio ficticio, mercadeo quiere lanzar en un mes una nueva presentación de un analgésico con la frase «alivio en 10 minutos» en el empaque, sin estudios que la respalden y con un arte distinto del aprobado. La analista de asuntos regulatorios dice que no es posible; el gerente comercial la acusa de «frenar el negocio» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar ciencia regulatoria y tendencias de transformación del INVIMA en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Ciencia regulatoria y tendencias de transformación del INVIMA»?","respuesta":"Interpreta el concepto de ciencia regulatoria y las iniciativas recientes de INVIMA (gestión de represamiento, digitalización, enfoque de riesgo)."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa funcional del área de asuntos regulatorios.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Ciencia regulatoria y tendencias de transformación del INVIMA se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Congreso de Investigación Sanitaria y Ensayos Clínicos: ciencia regulatoria en Colombia (programa 2026). INVIMA (ES)","url":"https://www.invima.gov.co/biblioteca/preview/145148"},{"cita":"[Página web] Latin America Roundup: INVIMA touts reform effort (2025). Regulatory Affairs Professionals Society (RAPS) (EN)","url":"https://www.raps.org/resource/latin-america-roundup-invima-touts-reform-effort.html"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente ciencia regulatoria y tendencias de transformación del INVIMA en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de ciencia regulatoria y tendencias de transformación del INVIMA"}],"keywords":["curso","asuntos","regulatorios","farmacéuticos","colombia","ciencia","regulatoria","tendencias","transformación","invima","unidad","fundamentos"],"mapa":{"centro":"Ciencia regulatoria y tendencias de transformación del INVIMA","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa funcional de un departamento de asuntos regulatorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las categorías de producto y sus normas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Diseña el inventario regulatorio (qué datos de cada registro se controlan).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón cuatro indicadores del área con fórmula y meta.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Ciencia regulatoria y tendencias de transformación del INVIMA","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico: Laboratorios Cóndor (ficticio) es titular de 40 registros de medicamentos (8 biológicos registrados hace años bajo el Decreto 677), 12 suplementos dietarios y 5 dispositivos médicos. Hoy no tiene un área de asuntos regulatorios: cada gerente de producto «lleva sus registros» en hojas de cálculo distintas, hubo un requerimiento vencido el año pasado y nadie sabe qué productos llevan más de 30 días sin comercializarse (datos simulados). La dirección quiere crear el área. La pregunta que decide esta clase es: Un gerente afirma que «la digitalización y el enfoque de riesgo del Invima significan que ya no hay que preparar bien los expedientes». ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es correcta: los trámites digitales se aprueban automáticamente, sin ninguna evaluación técnica del Invima.","correcta":false,"retro":"Digital no significa automático para todo trámite."},{"texto":"Es correcta si la empresa paga la tarifa del trámite prioritario que ofrece el Invima.","correcta":false,"retro":"La tarifa no cambia los requisitos de evidencia."},{"texto":"Es errada: la digitalización agiliza el trámite, pero la calidad de la evidencia sigue decidiendo.","correcta":true,"retro":"Correcto. Además, el control posterior puede llevar a suspender registros."},{"texto":"Es errada solo porque los expedientes digitales tienen que ser más extensos que los de papel.","correcta":false,"retro":"La extensión no es el punto."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
