    v_n := v_n + 1;
  END IF;

  -- 05. Caso: diseño del mapa funcional de un departamento de asuntos regulatorios
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: diseño del mapa funcional de un departamento de asuntos regulatorios$t$
     AND m.title = $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: diseño del mapa funcional de un departamento de asuntos regulatorios$t$, $u$Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: diseño del mapa funcional de un departamento de asuntos regulatorios","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de caso: diseño del mapa funcional de un departamento de asuntos regulatorios. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: diseño del mapa funcional de un departamento de asuntos regulatorios con tus propias palabras y reconocer por qué importa en curso de Asuntos Regulatorios Farmacéuticos en Colombia.","Relacionar caso: diseño del mapa funcional de un departamento de asuntos regulatorios con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: diseño del mapa funcional de un departamento de asuntos regulatorios y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica los conceptos de la unidad construyendo inventario, calendario de vencimientos, flujos e indicadores de un área de AR. aplicar los conceptos de la unidad diseñando el mapa funcional de un departamento de asuntos regulatorios en un laboratorio colombiano. Un departamento de AR típico se organiza por portafolio (síntesis química, biológicos, fitoterapéuticos/suplementos, dispositivos y cosméticos) o por proceso (nuevos registros, mantenimiento/ciclo de vida, publicidad y etiquetado, inteligencia regulatoria).…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso: diseño del mapa funcional de un departamento de asuntos regulatorios aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda la función regulatoria y el sistema sanitario colombiano, identifique el régimen aplicable a cada categoría de producto y su ciclo de vida, y formule estrategias e inteligencia regulatoria alineadas con la normativa vigente y la armonización internacional. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica los conceptos de la unidad construyendo inventario, calendario de vencimientos, flujos e indicadores de un área de AR. aplicar los conceptos de la unidad diseñando el mapa funcional de un departamento de asuntos regulatorios en un laboratorio colombiano. Un departamento de AR típico se organiza por portafolio (síntesis química, biológicos, fitoterapéuticos/suplementos, dispositivos y cosméticos) o por proceso (nuevos registros, mantenimiento/ciclo de vida, publicidad y etiquetado, inteligencia regulatoria).…","Una pregunta que se usa para comprobar esta clase es: «Un departamento de asuntos regulatorios mantiene un calendario de «vencimientos y renovaciones» de sus 40 registros de medicamentos. ¿Qué análisis es correcto con la norma vigente?» La respuesta correcta se apoya en lo siguiente: El Decreto 1474 de 2023 volvió indefinida la vigencia de los registros sanitarios de medicamentos, siempre que se mantengan las condiciones aprobadas. El seguimiento regulatorio se orienta a modificaciones, notificaciones de comercialización (artículo 18 del Decreto 334 de 2022), farmacovigilancia y requisitos de otras categorías. La fuente citada es: Decreto 1474 de 2023; Decreto 334 de 2022, artículo 18.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa funcional del área de asuntos regulatorios.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: diseño del mapa funcional de un departamento de asuntos regulatorios, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las categorías de producto y sus normas. Evidencia que debe quedar: Registro del paso.","Diseña el inventario regulatorio (qué datos de cada registro se controlan). Evidencia que debe quedar: Registro del paso.","Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos. Evidencia que debe quedar: Registro del paso.","Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste. Evidencia que debe quedar: Registro del paso.","Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables. Evidencia que debe quedar: Registro del paso.","Propón cuatro indicadores del área con fórmula y meta. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un laboratorio ficticio, mercadeo quiere lanzar en un mes una nueva presentación de un analgésico con la frase «alivio en 10 minutos» en el empaque, sin estudios que la respalden y con un arte distinto del aprobado. La analista de asuntos regulatorios dice que no es posible; el gerente comercial la acusa de «frenar el negocio» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: diseño del mapa funcional de un departamento de asuntos regulatorios en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: diseño del mapa funcional de un departamento de asuntos regulatorios»?","respuesta":"Aplica los conceptos de la unidad construyendo inventario, calendario de vencimientos, flujos e indicadores de un área de AR. aplicar los conceptos de la unidad diseñando el mapa funcional de un departamento de asuntos regulatorios en un laboratorio colombiano. Un departamento de AR típico se organiza por portafolio (síntesis química, biológicos, fitoterapéuticos/suplementos, dispositivos y cosméticos) o por proceso (nuevos registros, mantenimiento/ciclo de vida, publicidad y etiquetado, inteligencia regulatoria).…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa funcional del área de asuntos regulatorios.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso: diseño del mapa funcional de un departamento de asuntos regulatorios se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: diseño del mapa funcional de un departamento de asuntos regulatorios en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso: diseño del mapa funcional de un departamento de asuntos regulatorios"}],"keywords":["curso","asuntos","regulatorios","farmacéuticos","colombia","diseño","funcional","departamento","unidad","fundamentos","químico","farmacéutico"],"mapa":{"centro":"Caso: diseño del mapa funcional de un departamento de asuntos regulatorios","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa funcional de un departamento de asuntos regulatorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las categorías de producto y sus normas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Diseña el inventario regulatorio (qué datos de cada registro se controlan).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Construye el calendario de obligaciones con la norma vigente: modificaciones, notificaciones del artículo 18 del Decreto 334 de 2022, farmacovigilancia y los requisitos propios de suplementos y dispositivos.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué hacer con los biológicos registrados bajo el Decreto 677 y cita la fuente que verificaste.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Dibuja los flujos principales (nuevo registro, modificación, requerimiento, notificación) con sus responsables.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón cuatro indicadores del área con fórmula y meta.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Caso: diseño del mapa funcional de un departamento de asuntos regulatorios","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos de los asuntos regulatorios y rol del Químico Farmacéutico: Laboratorios Cóndor (ficticio) es titular de 40 registros de medicamentos (8 biológicos registrados hace años bajo el Decreto 677), 12 suplementos dietarios y 5 dispositivos médicos. Hoy no tiene un área de asuntos regulatorios: cada gerente de producto «lleva sus registros» en hojas de cálculo distintas, hubo un requerimiento vencido el año pasado y nadie sabe qué productos llevan más de 30 días sin comercializarse (datos simulados). La dirección quiere crear el área. La pregunta que decide esta clase es: Un departamento de asuntos regulatorios mantiene un calendario de «vencimientos y renovaciones» de sus 40 registros de medicamentos. ¿Qué análisis es correcto con la norma vigente?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"La vigencia es indefinida desde el Decreto 1474 de 2023: el calendario sigue modificaciones y notificaciones.","correcta":true,"retro":"Correcto. Las obligaciones cambian de forma, no desaparecen."},{"texto":"Es correcto: los registros de medicamentos se renuevan cada cinco años y el calendario es imprescindible para no perderlos.","correcta":false,"retro":"Ese régimen cambió con el Decreto 1474 de 2023."},{"texto":"Debe eliminarse todo seguimiento, porque un registro indefinido ya no tiene obligaciones asociadas.","correcta":false,"retro":"Siguen las modificaciones, las notificaciones, la farmacovigilancia y la vigilancia."},{"texto":"Solo hay que mantener las fechas de los registros de los productos biológicos y de las vacunas.","correcta":false,"retro":"La vigencia indefinida aplica a los medicamentos; el seguimiento de obligaciones es para todos."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 06. Introducción a la unidad: quién regula qué en Colombia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: quién regula qué en Colombia$t$
     AND m.title = $u$Unidad 2. Sistema sanitario y autoridades regulatorias$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción a la unidad: quién regula qué en Colombia$t$, $u$Unidad 2. Sistema sanitario y autoridades regulatorias$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción a la unidad: quién regula qué en Colombia","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de introducción a la unidad: quién regula qué en Colombia. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción a la unidad: quién regula qué en Colombia con tus propias palabras y reconocer por qué importa en curso de Asuntos Regulatorios Farmacéuticos en Colombia.","Relacionar introducción a la unidad: quién regula qué en Colombia con unidad 2. Sistema sanitario y autoridades regulatorias y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción a la unidad: quién regula qué en Colombia y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Resume la arquitectura del sistema de vigilancia sanitaria y las competencias de cada autoridad."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción a la unidad: quién regula qué en Colombia aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Sistema sanitario y autoridades regulatorias. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda la función regulatoria y el sistema sanitario colombiano, identifique el régimen aplicable a cada categoría de producto y su ciclo de vida, y formule estrategias e inteligencia regulatoria alineadas con la normativa vigente y la armonización internacional. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Resume la arquitectura del sistema de vigilancia sanitaria y las competencias de cada autoridad.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 2. Sistema sanitario y autoridades regulatorias y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de autoridades con respuestas a cinco consultas.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción a la unidad: quién regula qué en Colombia, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y describe cada situación. Evidencia que debe quedar: Registro del paso.","Identifica la autoridad competente de cada una y explica por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma que regula cada situación. Evidencia que debe quedar: Registro del paso.","Describe qué acciones puede tomar la autoridad (medidas, sanciones, requerimientos). Evidencia que debe quedar: Registro del paso.","Señala los casos en que más de una entidad puede intervenir y cómo se coordinan. Evidencia que debe quedar: Registro del paso.","Redacta una respuesta breve para cada consultante. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción a la unidad: quién regula qué en Colombia en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción a la unidad: quién regula qué en Colombia»?","respuesta":"Resume la arquitectura del sistema de vigilancia sanitaria y las competencias de cada autoridad."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de autoridades con respuestas a cinco consultas.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción a la unidad: quién regula qué en Colombia se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Sistema sanitario y autoridades regulatorias.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Cooperación internacional – El Instituto (ARNr nivel IV OPS, ICH, reconocimiento entre ARNr). INVIMA (ES)","url":"https://invima.gov.co/el-instituto/cooperacion-internacional"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción a la unidad: quién regula qué en Colombia en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción a la unidad: quién regula qué en Colombia"}],"keywords":["curso","asuntos","regulatorios","farmacéuticos","colombia","introducción","unidad","quién","regula","sistema","sanitario","autoridades"],"mapa":{"centro":"Introducción a la unidad: quién regula qué en Colombia","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 2. Sistema sanitario y autoridades regulatorias","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa de autoridades para cinco situaciones","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y describe cada situación.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica la autoridad competente de cada una y explica por qué.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Cita la norma que regula cada situación.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Describe qué acciones puede tomar la autoridad (medidas, sanciones, requerimientos).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala los casos en que más de una entidad puede intervenir y cómo se coordinan.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta una respuesta breve para cada consultante.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Mapa de autoridades para cinco situaciones","contexto":"La consultora ficticia RegulaPlus recibe cinco consultas (datos simulados): (1) una farmacia vende un medicamento en control directo por encima del precio máximo; (2) un laboratorio quiere saber si su planta cumple BPM antes de exportar; (3) una droguería almacena medicamentos al sol; (4) una IPS no tiene servicio farmacéutico habilitado; (5) un influenciador promociona un antibiótico de venta con fórmula. Debe responder qué autoridad es competente, con qué norma y qué puede hacer cada una.","pregunta":"¿Qué decisión demuestra que entendiste introducción a la unidad: quién regula qué en Colombia?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
