  END IF;

  -- 07. Ministerio de Salud y Ley Estatutaria 1751 de 2015: rector de la política farmacéutica
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Ministerio de Salud y Ley Estatutaria 1751 de 2015: rector de la política farmacéutica$t$
     AND m.title = $u$Unidad 2. Sistema sanitario y autoridades regulatorias$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Ministerio de Salud y Ley Estatutaria 1751 de 2015: rector de la política farmacéutica$t$, $u$Unidad 2. Sistema sanitario y autoridades regulatorias$u$;
