  -- 17. Medicamentos de síntesis química y biológicos (Decreto 1782 de 2014)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Medicamentos de síntesis química y biológicos (Decreto 1782 de 2014)$t$
     AND m.title = $u$Unidad 3. Marco normativo y categorías de productos$u$
   ORDER BY l.id LIMIT 1;
