  -- 24. Información y publicidad de medicamentos: Resolución 1896 de 2023
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Información y publicidad de medicamentos: Resolución 1896 de 2023$t$
     AND m.title = $u$Unidad 4. Ciclo de vida regulatorio, publicidad, precios y farmacovigilancia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Información y publicidad de medicamentos: Resolución 1896 de 2023$t$, $u$Unidad 4. Ciclo de vida regulatorio, publicidad, precios y farmacovigilancia$u$;
