       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 27. Sistema de Trámites en Línea e INVIMA a un clic
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Sistema de Trámites en Línea e INVIMA a un clic$t$
     AND m.title = $u$Unidad 4. Certificaciones, tarifas, tiempos y trámite en línea$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Sistema de Trámites en Línea e INVIMA a un clic$t$, $u$Unidad 4. Certificaciones, tarifas, tiempos y trámite en línea$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Sistema de Trámites en Línea e INVIMA a un clic","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de sistema de Trámites en Línea e INVIMA a un clic. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar sistema de Trámites en Línea e INVIMA a un clic con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos ante el INVIMA.","Relacionar sistema de Trámites en Línea e INVIMA a un clic con unidad 4. Certificaciones, tarifas, tiempos y trámite en línea y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar sistema de Trámites en Línea e INVIMA a un clic y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Reconoce las plataformas del INVIMA para radicar registros nuevos de medicamentos, la creación de usuario y la asignación del IUM al expedir el registro."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, sistema de Trámites en Línea e INVIMA a un clic aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Certificaciones, tarifas, tiempos y trámite en línea. El objetivo del curso es claro: Que el químico farmacéutico planee, prepare y radique una solicitud de registro sanitario nuevo de medicamento ante el INVIMA, eligiendo la ruta de evaluación y la modalidad correctas, reuniendo los requisitos del tipo de producto e interpretando los actos administrativos resultantes. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Reconoce las plataformas del INVIMA para radicar registros nuevos de medicamentos, la creación de usuario y la asignación del IUM al expedir el registro.","Una pregunta que se usa para comprobar esta clase es: «Un analista comparte su usuario de la plataforma de trámites del Invima con todo el equipo «para no depender de una persona». ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: Los usuarios de las plataformas de trámites son personales: compartirlos impide atribuir las actuaciones y compromete la seguridad. La continuidad se logra con usuarios propios para cada integrante y suplencias definidas. La fuente citada es: Buenas prácticas de seguridad de la información; condiciones de uso de las plataformas del Invima.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 4. Certificaciones, tarifas, tiempos y trámite en línea y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Lista de verificación con brechas y decisión de radicación.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar sistema de Trámites en Línea e INVIMA a un clic, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y arma la lista de verificación por bloques: legal, certificaciones, calidad, estabilidad, artes, tarifa y plataforma. Evidencia que debe quedar: Registro del paso.","Marca qué tiene la empresa y qué falta para cada ítem. Evidencia que debe quedar: Registro del paso.","Evalúa el riesgo del certificado de BPM que vence en cuatro meses. Evidencia que debe quedar: Registro del paso.","Evalúa si la estabilidad disponible sustenta la vida útil que se propondría. Evidencia que debe quedar: Registro del paso.","Indica qué documentos requieren traducción y qué verificaciones debes hacer en la norma vigente. Evidencia que debe quedar: Registro del paso.","Decide si se puede radicar en dos meses y con qué condiciones. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar sistema de Trámites en Línea e INVIMA a un clic en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Sistema de Trámites en Línea e INVIMA a un clic»?","respuesta":"Reconoce las plataformas del INVIMA para radicar registros nuevos de medicamentos, la creación de usuario y la asignación del IUM al expedir el registro."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Lista de verificación con brechas y decisión de radicación.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Sistema de Trámites en Línea e INVIMA a un clic se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Certificaciones, tarifas, tiempos y trámite en línea.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Ya se encuentra disponible la plataforma Invima a un clic para nuevos registros de medicamentos","url":"https://www.youtube.com/watch?v=TfuYCgUzPO0"},{"cita":"[Página web] Trámites en línea – Sistema de Trámites en Línea INVIMA. INVIMA (ES)","url":"https://www.invima.gov.co/tramites-y-servicios/tramites-en-linea"},{"cita":"[Página web] Circular 10798 de 2017 INVIMA – Asignación del IUM con la plataforma INVIMA a un Clic. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/circular_invima_10798_2017.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente sistema de Trámites en Línea e INVIMA a un clic en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de sistema de Trámites en Línea e INVIMA a un clic"}],"keywords":["curso","registro","sanitario","medicamentos","invima","sistema","trámites","línea","unidad","certificaciones","tarifas","tiempos"],"mapa":{"centro":"Sistema de Trámites en Línea e INVIMA a un clic","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 4. Certificaciones, tarifas, tiempos y trámite en línea","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Lista de verificación para radicar un genérico importado","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y arma la lista de verificación por bloques: legal, certificaciones, calidad, estabilidad, artes, tarifa y plataforma.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Marca qué tiene la empresa y qué falta para cada ítem.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Evalúa el riesgo del certificado de BPM que vence en cuatro meses.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Evalúa si la estabilidad disponible sustenta la vida útil que se propondría.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Indica qué documentos requieren traducción y qué verificaciones debes hacer en la norma vigente.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Decide si se puede radicar en dos meses y con qué condiciones.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Sistema de Trámites en Línea e INVIMA a un clic","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 4. Certificaciones, tarifas, tiempos y trámite en línea: Farmacéutica del Llano (ficticia) importará de Argentina tabletas recubiertas de un antihipertensivo incluido en las normas farmacológicas, en la modalidad importar y vender, para radicar el registro en dos meses (datos simulados). Tiene: el expediente técnico del fabricante en inglés, un certificado de BPM del fabricante que vence en cuatro meses, estabilidad a 30 °C / 75 % HR de 12 meses y acelerada de 6, y artes de empaque en borrador. La pregunta que decide esta clase es: Un analista comparte su usuario de la plataforma de trámites del Invima con todo el equipo «para no depender de una persona». ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es adecuado, porque así cualquier integrante del equipo puede radicar trámites a cualquier hora.","correcta":false,"retro":"La comodidad no justifica perder la trazabilidad."},{"texto":"Es adecuado si la contraseña del usuario compartido se cambia por lo menos una vez al año.","correcta":false,"retro":"Cambiar la contraseña no resuelve que varios usen el mismo usuario."},{"texto":"Es inadecuado solo porque compartir el usuario genera un costo adicional en la plataforma.","correcta":false,"retro":"El problema de fondo es la trazabilidad, no un costo."},{"texto":"Es inadecuado: cada persona tiene su usuario; compartirlo impide saber quién radicó qué.","correcta":true,"retro":"Correcto. La continuidad se resuelve con usuarios y suplencias propios."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 28. Caso práctico: radicación paso a paso de un registro sanitario nuevo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: radicación paso a paso de un registro sanitario nuevo$t$
     AND m.title = $u$Unidad 4. Certificaciones, tarifas, tiempos y trámite en línea$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: radicación paso a paso de un registro sanitario nuevo$t$, $u$Unidad 4. Certificaciones, tarifas, tiempos y trámite en línea$u$;
