      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases completas con experiencia interactiva (catálogo).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;
  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Registro Sanitario de Medicamentos ante el INVIMA$t$, v_n;
END $curso$;

-- ============================================================
--  Experiencias de clase: Curso de Renovación de Registros Sanitarios de Medicamentos
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  32 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Renovación de Registros Sanitarios de Medicamentos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Renovación de Registros Sanitarios de Medicamentos$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: por qué la renovación cambió de naturaleza
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: por qué la renovación cambió de naturaleza$t$
     AND m.title = $u$Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: por qué la renovación cambió de naturaleza$t$, $u$Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: por qué la renovación cambió de naturaleza","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de introducción al curso: por qué la renovación cambió de naturaleza. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: por qué la renovación cambió de naturaleza con tus propias palabras y reconocer por qué importa en curso de Renovación de Registros Sanitarios de Medicamentos.","Relacionar introducción al curso: por qué la renovación cambió de naturaleza con unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: por qué la renovación cambió de naturaleza y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Presenta el recorrido del curso y el giro normativo: del registro de cinco años con renovación a la vigencia indefinida de los medicamentos (Decreto 1474 de 2023) y a la gestión continua del registro."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción al curso: por qué la renovación cambió de naturaleza aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida. El objetivo del curso es claro: Que el estudiante gestione la vigencia y la actualización de los registros sanitarios de un portafolio farmacéutico ante el INVIMA, aplicando el régimen vigente (Decretos 334 de 2022 y 1474 de 2023, Decreto 1156 de 2018 para fitoterapéuticos) para evitar pérdidas de vigencia, suspensiones y desabastecimientos. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Presenta el recorrido del curso y el giro normativo: del registro de cinco años con renovación a la vigencia indefinida de los medicamentos (Decreto 1474 de 2023) y a la gestión continua del registro.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de estado del portafolio con acciones priorizadas.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: por qué la renovación cambió de naturaleza, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Determina el régimen de vigencia de cada registro con la norma que lo sustenta. Evidencia que debe quedar: Registro del paso.","Explica qué ocurre con el registro de 2021 que «vencía» en 2026. Evidencia que debe quedar: Registro del paso.","Define qué hacer con el CPP del importado y por qué importa aunque el registro sea indefinido. Evidencia que debe quedar: Registro del paso.","Calcula cuándo vence el fitoterapéutico de 2016 y qué condiciones debe cumplir para una renovación automática. Evidencia que debe quedar: Registro del paso.","Analiza el fitoterapéutico vencido: qué puede hacer con las existencias y con el material de empaque. Evidencia que debe quedar: Registro del paso.","Prioriza las cuatro situaciones y justifica el orden. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: por qué la renovación cambió de naturaleza en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: por qué la renovación cambió de naturaleza»?","respuesta":"Presenta el recorrido del curso y el giro normativo: del registro de cinco años con renovación a la vigencia indefinida de los medicamentos (Decreto 1474 de 2023) y a la gestión continua del registro."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de estado del portafolio con acciones priorizadas.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción al curso: por qué la renovación cambió de naturaleza se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Capacitación - Trámite de Registro Sanitario de Medicamentos en Invima a un clic","url":"https://www.youtube.com/watch?v=kMhjktRya9w"},{"cita":"Opinión Jurídica Nº 107: Novedades en el registro sanitario de los medicamentos. Decreto 1474 de 2023. INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/archivosExternos/doc_invima_0005_2023.pdf"},{"cita":"[Página web] Medicamentos con registro sanitario del Invima tendrán vigencia indefinida: ya no será de cinco años. Blu Radio (ES)","url":"https://www.bluradio.com/nacion/medicamentos-con-registro-sanitario-del-invima-tendran-vigencia-indefinida-ya-no-sera-de-cinco-anos-rg10"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: por qué la renovación cambió de naturaleza en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción al curso: por qué la renovación cambió de naturaleza"}],"keywords":["curso","renovación","registros","sanitarios","medicamentos","introducción","cambió","naturaleza","unidad","vigencia","registro","sanitario"],"mapa":{"centro":"Introducción al curso: por qué la renovación cambió de naturaleza","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Estado de los registros de un portafolio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Determina el régimen de vigencia de cada registro con la norma que lo sustenta.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Explica qué ocurre con el registro de 2021 que «vencía» en 2026.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define qué hacer con el CPP del importado y por qué importa aunque el registro sea indefinido.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Calcula cuándo vence el fitoterapéutico de 2016 y qué condiciones debe cumplir para una renovación automática.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Analiza el fitoterapéutico vencido: qué puede hacer con las existencias y con el material de empaque.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prioriza las cuatro situaciones y justifica el orden.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Estado de los registros de un portafolio","contexto":"Laboratorios Sabana (ficticio) te entrega cuatro registros consultados en la base del Invima (datos simulados): (1) tabletas de síntesis química concedidas en 2021, que «vencían» en 2026; (2) un jarabe importado concedido en 2019, con CPP que vence en seis meses; (3) un fitoterapéutico en cápsulas concedido en 2016; (4) un fitoterapéutico tópico cuyo registro venció hace dos meses sin solicitud de renovación, con existencias en bodega y material de empaque impreso.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: por qué la renovación cambió de naturaleza?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Decreto 677 de 1995 y Decreto 2086 de 2010: vigencia de cinco años y renovación anticipada
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Decreto 677 de 1995 y Decreto 2086 de 2010: vigencia de cinco años y renovación anticipada$t$
     AND m.title = $u$Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Decreto 677 de 1995 y Decreto 2086 de 2010: vigencia de cinco años y renovación anticipada$t$, $u$Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida$u$;
