  -- 05. Medicamentos con vigencia indefinida vs. fitoterapéuticos con vigencia de diez años
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Medicamentos con vigencia indefinida vs. fitoterapéuticos con vigencia de diez años$t$
     AND m.title = $u$Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Medicamentos con vigencia indefinida vs. fitoterapéuticos con vigencia de diez años$t$, $u$Unidad 1. Vigencia del registro sanitario: de la renovación quinquenal a la vigencia indefinida$u$;
