  -- 12. Caso: biológico aprobado bajo el Decreto 677 que debe migrar
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: biológico aprobado bajo el Decreto 677 que debe migrar$t$
     AND m.title = $u$Unidad 2. Requisitos de renovación y transición por tipo de producto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
