      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 18. Caso: renovación con modificaciones simultáneas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: renovación con modificaciones simultáneas$t$
     AND m.title = $u$Unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: renovación con modificaciones simultáneas$t$, $u$Unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: renovación con modificaciones simultáneas","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de caso: renovación con modificaciones simultáneas. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: renovación con modificaciones simultáneas con tus propias palabras y reconocer por qué importa en curso de Renovación de Registros Sanitarios de Medicamentos.","Relacionar caso: renovación con modificaciones simultáneas con unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: renovación con modificaciones simultáneas y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Resuelve un caso en que coinciden cambio de fabricante, ampliación de vida útil y actualización de inserto, comparando el manejo bajo el Decreto 334 y bajo la vigencia indefinida. resolver cómo se gestionaba una renovación con cambios simultáneos bajo el Decreto 334 de 2022 y cómo se gestiona hoy, con registros de vigencia indefinida, la necesidad de actualizar varios aspectos de un registro al mismo tiempo.…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso: renovación con modificaciones simultáneas aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP. El objetivo del curso es claro: Que el estudiante gestione la vigencia y la actualización de los registros sanitarios de un portafolio farmacéutico ante el INVIMA, aplicando el régimen vigente (Decretos 334 de 2022 y 1474 de 2023, Decreto 1156 de 2018 para fitoterapéuticos) para evitar pérdidas de vigencia, suspensiones y desabastecimientos. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Resuelve un caso en que coinciden cambio de fabricante, ampliación de vida útil y actualización de inserto, comparando el manejo bajo el Decreto 334 y bajo la vigencia indefinida. resolver cómo se gestionaba una renovación con cambios simultáneos bajo el Decreto 334 de 2022 y cómo se gestiona hoy, con registros de vigencia indefinida, la necesidad de actualizar varios aspectos de un registro al mismo tiempo.…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: renovación con modificaciones simultáneas, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un laboratorio ficticio con 40 registros indefinidos descubre en una auditoría (datos simulados): insertos sin las últimas advertencias de seguridad, un CPP vencido, un fabricante de principio activo cambiado sin trámite y estudios de estabilidad que no respaldan la vida útil impresa. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: renovación con modificaciones simultáneas en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: renovación con modificaciones simultáneas»?","respuesta":"Resuelve un caso en que coinciden cambio de fabricante, ampliación de vida útil y actualización de inserto, comparando el manejo bajo el Decreto 334 y bajo la vigencia indefinida. resolver cómo se gestionaba una renovación con cambios simultáneos bajo el Decreto 334 de 2022 y cómo se gestiona hoy, con registros de vigencia indefinida, la necesidad de actualizar varios aspectos de un registro al mismo tiempo.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso: renovación con modificaciones simultáneas se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: renovación con modificaciones simultáneas en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso: renovación con modificaciones simultáneas"}],"keywords":["curso","renovación","registros","sanitarios","medicamentos","modificaciones","simultáneas","unidad","actualización","información","técnica","estabilidad"],"mapa":{"centro":"Caso: renovación con modificaciones simultáneas","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Caso: renovación con modificaciones simultáneas","contexto":"Un laboratorio ficticio con 40 registros indefinidos descubre en una auditoría (datos simulados): insertos sin las últimas advertencias de seguridad, un CPP vencido, un fabricante de principio activo cambiado sin trámite y estudios de estabilidad que no respaldan la vida útil impresa.","pregunta":"¿Qué decisión demuestra que entendiste caso: renovación con modificaciones simultáneas?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 19. Proyecto de decreto 2026: nuevas rutas de modificación (IA, IA-IN, IB, II, URG)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Proyecto de decreto 2026: nuevas rutas de modificación (IA, IA-IN, IB, II, URG)$t$
     AND m.title = $u$Unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Proyecto de decreto 2026: nuevas rutas de modificación (IA, IA-IN, IB, II, URG)$t$, $u$Unidad 3. Actualización de la información técnica: estabilidad, BPM, insertos y CPP$u$;
