  -- 06. Guías INVIMA de modificaciones vigentes y cómo usarlas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Guías INVIMA de modificaciones vigentes y cómo usarlas$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de las modificaciones al registro sanitario$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Guías INVIMA de modificaciones vigentes y cómo usarlas$t$, $u$Unidad 1. Fundamentos y marco normativo de las modificaciones al registro sanitario$u$;
