     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 25. Casos simulados de cambios en biotecnológicos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Casos simulados de cambios en biotecnológicos$t$
     AND m.title = $u$Unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Casos simulados de cambios en biotecnológicos$t$, $u$Unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Casos simulados de cambios en biotecnológicos","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de casos simulados de cambios en biotecnológicos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar casos simulados de cambios en biotecnológicos con tus propias palabras y reconocer por qué importa en curso de Modificaciones al Registro Sanitario de Medicamentos.","Relacionar casos simulados de cambios en biotecnológicos con unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar casos simulados de cambios en biotecnológicos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica las categorías de riesgo a casos simulados de cambios de calidad en productos bioterapéuticos."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, casos simulados de cambios en biotecnológicos aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos. El objetivo del curso es claro: Que el participante clasifique, documente y radique correctamente ante el INVIMA las modificaciones al registro sanitario de medicamentos de síntesis química y biológicos, integrándolas al control de cambios del sistema de calidad y planeando su agrupación, costo y cronograma. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica las categorías de riesgo a casos simulados de cambios de calidad en productos bioterapéuticos.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de gestión del cambio urgente de seguridad.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar casos simulados de cambios en biotecnológicos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Analiza si el cambio es urgente de seguridad o de etiquetado y justifica. Evidencia que debe quedar: Registro del paso.","Describe la vía del artículo 8 y los plazos que aplican. Evidencia que debe quedar: Registro del paso.","Define el texto que propondrías para el inserto (advertencia y recomendación). Evidencia que debe quedar: Registro del paso.","Planea la comunicación a profesionales mientras se actualiza el inserto. Evidencia que debe quedar: Registro del paso.","Decide qué hacer con las unidades en el mercado y los insertos impresos. Evidencia que debe quedar: Registro del paso.","Define la gestión de farmacovigilancia relacionada. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Una agencia internacional comunica un riesgo grave de un principio activo que un laboratorio ficticio comercializa en Colombia (datos simulados). El área comercial quiere «esperar el trámite normal» para no cambiar los empaques en inventario; el área de farmacovigilancia quiere actuar ya. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar casos simulados de cambios en biotecnológicos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Casos simulados de cambios en biotecnológicos»?","respuesta":"Aplica las categorías de riesgo a casos simulados de cambios de calidad en productos bioterapéuticos."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de gestión del cambio urgente de seguridad.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Casos simulados de cambios en biotecnológicos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Quality changes to approved biotherapeutic product: simulated case studies on reporting categories & supporting data requirements. NCBI PMC (EN)","url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6863427/"},{"cita":"Post-approval Changes for Biologics in Latin American Markets. EFPIA (EN)","url":"https://efpia.eu/media/413202/post-approval-changes-for-biologics-in-latin-american-markets.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente casos simulados de cambios en biotecnológicos en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de casos simulados de cambios en biotecnológicos"}],"keywords":["curso","modificaciones","registro","sanitario","medicamentos","casos","simulados","cambios","biotecnológicos","unidad","seguridad","eficacia"],"mapa":{"centro":"Casos simulados de cambios en biotecnológicos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Gestión de un cambio urgente de seguridad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Analiza si el cambio es urgente de seguridad o de etiquetado y justifica.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Describe la vía del artículo 8 y los plazos que aplican.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define el texto que propondrías para el inserto (advertencia y recomendación).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Planea la comunicación a profesionales mientras se actualiza el inserto.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Decide qué hacer con las unidades en el mercado y los insertos impresos.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Define la gestión de farmacovigilancia relacionada.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Gestión de un cambio urgente de seguridad","contexto":"Farmacéutica Litoral (ficticia) recibe una alerta de una agencia internacional: su medicamento puede causar una reacción cutánea grave en pacientes con un alelo genético frecuente en ciertas poblaciones (datos simulados). El inserto colombiano no menciona este riesgo. La empresa tiene 30.000 unidades en el mercado y 50.000 insertos impresos.","pregunta":"¿Qué decisión demuestra que entendiste casos simulados de cambios en biotecnológicos?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 26. Caso: señal de farmacovigilancia que exige cambio urgente de inserto
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: señal de farmacovigilancia que exige cambio urgente de inserto$t$
     AND m.title = $u$Unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: señal de farmacovigilancia que exige cambio urgente de inserto$t$, $u$Unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: señal de farmacovigilancia que exige cambio urgente de inserto","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de caso: señal de farmacovigilancia que exige cambio urgente de inserto. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: señal de farmacovigilancia que exige cambio urgente de inserto con tus propias palabras y reconocer por qué importa en curso de Modificaciones al Registro Sanitario de Medicamentos.","Relacionar caso: señal de farmacovigilancia que exige cambio urgente de inserto con unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: señal de farmacovigilancia que exige cambio urgente de inserto y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Ejecuta la gestión de un cambio urgente de seguridad y su posterior solicitud formal ante el INVIMA. gestionar un cambio urgente de seguridad y la posterior actualización del inserto e información para prescribir siguiendo la guía ASS-RSA-GU79 y el instructivo ACOM-INS80. el Decreto 334 de 2022 y la guía de seguridad y eficacia distinguen cuatro categorías: (1) cambios administrativos del etiquetado (p. ej., actualizar el código QR), que se implementan de inmediato por notificación o modificación automática y no se agrupan con las demás;…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso: señal de farmacovigilancia que exige cambio urgente de inserto aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos. El objetivo del curso es claro: Que el participante clasifique, documente y radique correctamente ante el INVIMA las modificaciones al registro sanitario de medicamentos de síntesis química y biológicos, integrándolas al control de cambios del sistema de calidad y planeando su agrupación, costo y cronograma. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Ejecuta la gestión de un cambio urgente de seguridad y su posterior solicitud formal ante el INVIMA. gestionar un cambio urgente de seguridad y la posterior actualización del inserto e información para prescribir siguiendo la guía ASS-RSA-GU79 y el instructivo ACOM-INS80. el Decreto 334 de 2022 y la guía de seguridad y eficacia distinguen cuatro categorías: (1) cambios administrativos del etiquetado (p. ej., actualizar el código QR), que se implementan de inmediato por notificación o modificación automática y no se agrupan con las demás;…","Una pregunta que se usa para comprobar esta clase es: «Una señal de farmacovigilancia exige agregar con urgencia una advertencia grave al inserto. ¿Qué vía prevé el Decreto 334 de 2022?» La respuesta correcta se apoya en lo siguiente: Según el artículo 8.3.2 del Decreto 334 de 2022, los cambios urgentes de seguridad se notifican y se implementan con acuerdo previo del Invima; el titular debe radicar la solicitud de aprobación dentro del mes siguiente. La fuente citada es: Decreto 334 de 2022, art. 8.3.2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de gestión del cambio urgente de seguridad.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: señal de farmacovigilancia que exige cambio urgente de inserto, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Analiza si el cambio es urgente de seguridad o de etiquetado y justifica. Evidencia que debe quedar: Registro del paso.","Describe la vía del artículo 8 y los plazos que aplican. Evidencia que debe quedar: Registro del paso.","Define el texto que propondrías para el inserto (advertencia y recomendación). Evidencia que debe quedar: Registro del paso.","Planea la comunicación a profesionales mientras se actualiza el inserto. Evidencia que debe quedar: Registro del paso.","Decide qué hacer con las unidades en el mercado y los insertos impresos. Evidencia que debe quedar: Registro del paso.","Define la gestión de farmacovigilancia relacionada. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: señal de farmacovigilancia que exige cambio urgente de inserto en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: señal de farmacovigilancia que exige cambio urgente de inserto»?","respuesta":"Ejecuta la gestión de un cambio urgente de seguridad y su posterior solicitud formal ante el INVIMA. gestionar un cambio urgente de seguridad y la posterior actualización del inserto e información para prescribir siguiendo la guía ASS-RSA-GU79 y el instructivo ACOM-INS80. el Decreto 334 de 2022 y la guía de seguridad y eficacia distinguen cuatro categorías: (1) cambios administrativos del etiquetado (p. ej., actualizar el código QR), que se implementan de inmediato por notificación o modificación automática y no se agrupan con las demás;…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de gestión del cambio urgente de seguridad.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso: señal de farmacovigilancia que exige cambio urgente de inserto se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: señal de farmacovigilancia que exige cambio urgente de inserto en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso: señal de farmacovigilancia que exige cambio urgente de inserto"}],"keywords":["curso","modificaciones","registro","sanitario","medicamentos","señal","farmacovigilancia","exige","cambio","urgente","inserto","unidad"],"mapa":{"centro":"Caso: señal de farmacovigilancia que exige cambio urgente de inserto","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Gestión de un cambio urgente de seguridad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Analiza si el cambio es urgente de seguridad o de etiquetado y justifica.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Describe la vía del artículo 8 y los plazos que aplican.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define el texto que propondrías para el inserto (advertencia y recomendación).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Planea la comunicación a profesionales mientras se actualiza el inserto.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Decide qué hacer con las unidades en el mercado y los insertos impresos.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Define la gestión de farmacovigilancia relacionada.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Caso: señal de farmacovigilancia que exige cambio urgente de inserto","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 4. Modificaciones de seguridad y eficacia (farmacológicas) y modificaciones de biológicos: Farmacéutica Litoral (ficticia) recibe una alerta de una agencia internacional: su medicamento puede causar una reacción cutánea grave en pacientes con un alelo genético frecuente en ciertas poblaciones (datos simulados). El inserto colombiano no menciona este riesgo. La empresa tiene 30.000 unidades en el mercado y 50.000 insertos impresos. La pregunta que decide esta clase es: Una señal de farmacovigilancia exige agregar con urgencia una advertencia grave al inserto. ¿Qué vía prevé el Decreto 334 de 2022?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Implementar el cambio con acuerdo previo del Invima y radicar la solicitud de aprobación dentro del mes siguiente.","correcta":true,"retro":"Correcto. Es la vía de los cambios urgentes de seguridad."},{"texto":"Esperar la aprobación previa de hasta 10 meses antes de cambiar cualquier texto del inserto.","correcta":false,"retro":"Ese plazo es de los cambios de seguridad y eficacia."},{"texto":"Cambiar el inserto sin informar al Invima, porque se trata de proteger a los pacientes.","correcta":false,"retro":"Se requiere el acuerdo previo y la radicación."},{"texto":"Notificar la novedad un año después de implementar el nuevo texto del inserto.","correcta":false,"retro":"Ese plazo es de las notificaciones administrativas."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
