  -- 11. Resúmenes y visiones generales no clínicas y clínicas (2.4–2.7)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Resúmenes y visiones generales no clínicas y clínicas (2.4–2.7)$t$
     AND m.title = $u$Unidad 2. Módulo 1 regional (Colombia) y Módulo 2: resúmenes$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Resúmenes y visiones generales no clínicas y clínicas (2.4–2.7)$t$, $u$Unidad 2. Módulo 1 regional (Colombia) y Módulo 2: resúmenes$u$;
