    v_n := v_n + 1;
  END IF;

  -- 22. 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)$t$
     AND m.title = $u$Unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P)$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)$t$, $u$Unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P)$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb). Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) con tus propias palabras y reconocer por qué importa en curso de Elaboración de Dossiers Farmacéuticos.","Relacionar 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) con unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P) y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe cómo presentar el sistema de envase-cierre y el resumen, protocolo, compromisos y datos de estabilidad conforme a la guía colombiana."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P). El objetivo del curso es claro: Que el químico farmacéutico sea capaz de armar, revisar y gestionar electrónicamente un dossier de medicamento de síntesis química (especialmente genérico) con estructura CTD, coherente entre módulos y alineado con los requisitos del INVIMA y de las autoridades de referencia de Latam. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe cómo presentar el sistema de envase-cierre y el resumen, protocolo, compromisos y datos de estabilidad conforme a la guía colombiana.","Una pregunta que se usa para comprobar esta clase es: «Un genérico se comercializará en Colombia. ¿Qué condiciones de estudio de estabilidad a largo plazo corresponden según la guía colombiana?» La respuesta correcta se apoya en lo siguiente: La Resolución 3157 de 2018 (guía de estudios de estabilidad) ubica a Colombia en la zona climática IVb, con condiciones de largo plazo de 30 °C y 75 % de humedad relativa, salvo productos que requieren almacenamiento especial. La fuente citada es: Resolución 3157 de 2018.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P) y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de revisión de la sección 3.2.P con puntos de mejora.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb), sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Asigna cada documento a su sección de 3.2.P. Evidencia que debe quedar: Registro del paso.","Verifica la coherencia entre la fórmula del lote y la validación del proceso. Evidencia que debe quedar: Registro del paso.","Revisa si los métodos tienen el soporte adecuado (validación o verificación). Evidencia que debe quedar: Registro del paso.","Revisa si la estabilidad respalda la vida útil propuesta y si las condiciones corresponden a Colombia. Evidencia que debe quedar: Registro del paso.","Revisa si el envase-cierre está bien documentado. Evidencia que debe quedar: Registro del paso.","Lista los puntos que generarían requerimientos y cómo resolverlos. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)»?","respuesta":"Describe cómo presentar el sistema de envase-cierre y el resumen, protocolo, compromisos y datos de estabilidad conforme a la guía colombiana."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de revisión de la sección 3.2.P con puntos de mejora.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P).","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Herramientas estadísticas para analizar la estabilidad de medicamentos y fármacos","url":"https://www.youtube.com/watch?v=dEBlmADVsXQ"},{"cita":"Documento de preguntas y respuestas – Resolución 3157 de 2018 (Guía de estabilidad de medicamentos de síntesis química), v. abril 2024. INVIMA (ES)","url":"https://www.invima.gov.co/invima_website/static/attachments/medicamentos_autorizacion_de_comercializacion_registros/Preguntas_20y_20respuestas_20Res._203157_20de_202018_20-_20Abril_202024_20V.6.pdf"},{"cita":"ICH Q1A(R2) Stability Testing of New Drug Substances and Products (Step 4). ICH (EN)","url":"https://database.ich.org/sites/default/files/Q1A(R2)%20Step4.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb) en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de 3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)"}],"keywords":["curso","elaboración","dossiers","farmacéuticos","envase","estabilidad","unidad","módulo","calidad","producto","terminado"],"mapa":{"centro":"3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P)","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Armado y revisión de la sección 3.2.P de una tableta genérica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Asigna cada documento a su sección de 3.2.P.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Verifica la coherencia entre la fórmula del lote y la validación del proceso.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Revisa si los métodos tienen el soporte adecuado (validación o verificación).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa si la estabilidad respalda la vida útil propuesta y si las condiciones corresponden a Colombia.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Revisa si el envase-cierre está bien documentado.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Lista los puntos que generarían requerimientos y cómo resolverlos.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"3.2.P.7–3.2.P.8: envase y estabilidad (Res. 3157 de 2018 y zona IVb)","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P): Te entregan los documentos de tabletas de atorvastatina 20 mg de Laboratorios Sierra (ficticia) (datos simulados): composición por tableta; proceso de granulación húmeda con fórmula de lote de 200.000 tabletas; validación del proceso en tres lotes de 50.000; especificaciones con disolución, valoración e impurezas; método de disolución propio validado y método de valoración farmacopeico; blíster de PVC/aluminio; estabilidad a 30 °C y 75 % HR de tres lotes por 18 meses con vida útil propuesta de 24 meses. La pregunta que decide esta clase es: Un genérico se comercializará en Colombia. ¿Qué condiciones de estudio de estabilidad a largo plazo corresponden según la guía colombiana?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Las de la zona climática IVb: 30 °C y 75 % de humedad relativa.","correcta":true,"retro":"Correcto. Es la zona asignada a Colombia."},{"texto":"Las de la zona climática II: 25 °C y 60 % de humedad relativa.","correcta":false,"retro":"No es la zona que exige la guía colombiana."},{"texto":"Refrigeración a 5 °C para todos los medicamentos, sin importar su forma farmacéutica.","correcta":false,"retro":"La refrigeración aplica solo a productos que la requieren."},{"texto":"Cualquier condición que elija el fabricante, porque la guía no fija condiciones.","correcta":false,"retro":"La guía fija condiciones."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 23. Caso práctico: armar la sección 3.2.P de una tableta genérica
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: armar la sección 3.2.P de una tableta genérica$t$
     AND m.title = $u$Unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P)$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: armar la sección 3.2.P de una tableta genérica$t$, $u$Unidad 4. Módulo 3 Calidad II: el producto terminado (3.2.P)$u$;
